const cfg = $input.first().json;

// Build one item per competitor — skip any with empty or invalid URL
const competitors = [
  { name: cfg.competitor1Name, rss: cfg.competitor1RssUrl },
  { name: cfg.competitor2Name, rss: cfg.competitor2RssUrl },
  { name: cfg.competitor3Name, rss: cfg.competitor3RssUrl }
].filter(c => c.rss && c.rss.startsWith('http') && !c.rss.includes('YOUR_'));

if (competitors.length === 0) {
  throw new Error('No valid competitor RSS URLs found. Add at least one RSS URL starting with http.');
}

// Return one item per competitor — the rest of the workflow runs once per competitor
// isLastCompetitor flag on the final item triggers the Gmail digest after all are processed
return competitors.map((c, index) => ({
  json: {
    competitorName: c.name,
    rssUrl: c.rss,
    isLastCompetitor: index === competitors.length - 1,
    competitorIndex: index + 1,
    totalCompetitors: competitors.length,
    weekLabel: cfg.weekLabel,
    yourNiche: cfg.yourNiche,
    recipientEmail: cfg.recipientEmail,
    senderName: cfg.senderName,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName
  }
}));

const response = $input.first().json;
const competitorData = $('Build the competitor list').item.json;

// Get raw RSS XML — handle errors gracefully
let rawXml = '';
try {
  rawXml = typeof response === 'string' ? response : (response?.data || '');
} catch (e) {
  rawXml = '';
}

// If RSS fetch failed or returned nothing useful
if (!rawXml || rawXml.length < 50 || response?.error) {
  return [{
    json: {
      ...competitorData,
      posts: [],
      postCount: 0,
      loggedAt: new Date().toISOString().replace('T', ' ').substring(0, 16),
      parseNote: 'Could not fetch RSS for ' + competitorData.competitorName
    }
  }];
}

// Extract individual RSS items using string matching
// Works for standard RSS 2.0 and Atom feeds
const itemMatches = rawXml.match(/<item[^>]*>[\s\S]*?<\/item>/gi) ||
                    rawXml.match(/<entry[^>]*>[\s\S]*?<\/entry>/gi) || [];

// Parse the most recent 5 posts
const posts = itemMatches.slice(0, 5).map(item => {
  // Title — handle both CDATA and plain text formats
  const titleMatch =
    item.match(/<title[^>]*><!\[CDATA\[([\s\S]*?)\]\]><\/title>/i) ||
    item.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = (titleMatch?.[1] || '').replace(/<[^>]+>/g, '').trim();

  // Publication date
  const dateMatch =
    item.match(/<pubDate[^>]*>([^<]+)<\/pubDate>/i) ||
    item.match(/<published[^>]*>([^<]+)<\/published>/i) ||
    item.match(/<updated[^>]*>([^<]+)<\/updated>/i);
  const rawDate = (dateMatch?.[1] || '').trim();
  const date = rawDate ? rawDate.substring(0, 16) : '';

  return { title, date };
}).filter(p => p.title && p.title.length > 3);

const loggedAt = new Date().toISOString().replace('T', ' ').substring(0, 16);

return [{
  json: {
    ...competitorData,
    posts,
    postCount: posts.length,
    loggedAt
  }
}];

const allRows = $input.all().map(i => i.json);
const config = $('Build the competitor list').item.json;

if (allRows.length === 0) {
  return [{
    json: {
      competitorData: 'No competitor content found this week.',
      weekLabel: config.weekLabel,
      yourNiche: config.yourNiche,
      competitorCount: 0,
      recipientEmail: config.recipientEmail,
      senderName: config.senderName
    }
  }];
}

// Build a structured text summary of what each competitor published
const competitorData = allRows.map(row => {
  const posts = [];
  if (row['Post 1 Title'] && row['Post 1 Title'].length > 3) posts.push(row['Post 1 Title']);
  if (row['Post 2 Title'] && row['Post 2 Title'].length > 3) posts.push(row['Post 2 Title']);
  if (row['Post 3 Title'] && row['Post 3 Title'].length > 3) posts.push(row['Post 3 Title']);
  if (row['Post 4 Title'] && row['Post 4 Title'].length > 3) posts.push(row['Post 4 Title']);
  if (row['Post 5 Title'] && row['Post 5 Title'].length > 3) posts.push(row['Post 5 Title']);

  return (
    row.Competitor + ':\n' +
    (posts.length > 0
      ? posts.map((p, i) => '  ' + (i + 1) + '. ' + p).join('\n')
      : '  No new posts found this week')
  );
}).join('\n\n');

return [{
  json: {
    competitorData,
    weekLabel: config.weekLabel,
    yourNiche: config.yourNiche,
    competitorCount: allRows.length,
    recipientEmail: config.recipientEmail,
    senderName: config.senderName
  }
}];

const gptOut = $input.first().json.output;
const digestData = $('Prepare the data for GPT').item.json;

if (!gptOut) {
  throw new Error('GPT did not return digest data. Check your OpenAI credential.');
}

const weekLabel = digestData.weekLabel;
const senderName = digestData.senderName;
const niche = digestData.yourNiche;

const highlights = (gptOut.competitorHighlights || []).map(h =>
  h.name + '\n' +
  'Top post this week: ' + h.topPost + '\n' +
  'Their strategy angle: ' + h.angle
).join('\n\n');

const trendingTopics = (gptOut.trendingTopics || []).map((t, i) => (i + 1) + '. ' + t).join('\n');
const contentGaps = (gptOut.contentGaps || []).map((t, i) => (i + 1) + '. ' + t).join('\n');
const urgentOpp = gptOut.urgentOpportunity || 'Not identified this week.';
const weekSummary = gptOut.weekSummary || '';

const emailBody =
  'Hello ' + senderName + ',\n\n' +
  'Here is your weekly competitive content intelligence digest.\n\n' +
  'Week: ' + weekLabel + '\n' +
  'Niche: ' + niche + '\n\n' +
  '============================================================\n' +
  'WEEK IN REVIEW\n' +
  '============================================================\n\n' +
  weekSummary + '\n\n' +
  '============================================================\n' +
  'WHAT EACH COMPETITOR PUBLISHED\n' +
  '============================================================\n\n' +
  highlights + '\n\n' +
  '============================================================\n' +
  'TRENDING TOPICS ACROSS ALL COMPETITORS\n' +
  '============================================================\n\n' +
  trendingTopics + '\n\n' +
  '============================================================\n' +
  'CONTENT GAPS — TOPICS NO COMPETITOR COVERED\n' +
  '============================================================\n\n' +
  contentGaps + '\n\n' +
  '============================================================\n' +
  'THIS WEEK\'S URGENT CONTENT OPPORTUNITY\n' +
  '============================================================\n\n' +
  urgentOpp + '\n\n' +
  'All competitor posts are saved in your Google Sheets Competitor Content tab.\n\n' +
  'Best regards,\n' + senderName;

return [{
  json: {
    emailSubject: 'Weekly Competitive Digest — ' + weekLabel,
    emailBody,
    recipientEmail: digestData.recipientEmail
  }
}];
